  ?product a pv:Hardware ;
            pv:hasCategory ?category .
  ?product1 a pv:Hardware ;
           pv:width_mm ?w1 ;
           pv:weight_g ?h1 .
  ?product2 a pv:Hardware ;
           pv:width_mm ?w2 ;
           pv:weight_g ?h2 .
